private int knapsack(int[] values, int[] weights, int cap, int i, int[][] memo) {
    if (i == values.length || cap == 0) {
        return 0;
    }
    if (memo[i][cap] != -1) {
        return memo[i][cap];
    }
    int skip = knapsack(values, weights, cap, i + 1, memo);
    int pick = 0;
    if (weights[i] <= cap) {
        pick = values[i] + knapsack(values, weights, cap - weights[i], i + 1, memo);
    }                                                          // ^ i + 1 = each item once
    memo[i][cap] = Math.max(pick, skip);
    return memo[i][cap];
}

